import{_ as t,V as p,W as c,X as o,Z as n,a1 as a,$ as e,Y as i,F as l}from"./framework-b1bd8911.js";const d={},u=n("blockquote",null,[n("p",null,'audio-plugin 最早的需求背景非常典型：微信语音是 amr 格式，html5 页面的 audio 标签直接播放不了，必须先转成 mp3；而 Java 自身很难搞定 amr 的编解码，所以插件选择了业界最成熟的 ffmpeg 来干这个脏活，Java 这边只负责"拼命令行 + 执行 + 处理临时文件"。')],-1),r=i(`<p>本篇作为 audio-plugin 的第一篇，手把手带大家把&quot;音频转码&quot;这个能力跑起来，包括环境安装、依赖引入、基本使用、参数说明，以及实际使用时踩过的坑。</p><h2 id="i-问题背景" tabindex="-1"><a class="header-anchor" href="#i-问题背景" aria-hidden="true">#</a> I. 问题背景</h2><p>音频转码这个事，说起来简单：给一个 <code>.amr</code> 文件，吐一个 <code>.mp3</code> 出来。但要自己实现就没那么轻松了——</p><ul><li>音频编解码是重活，amr、mp3、ogg、aac 每种格式的编解码器都不一样，Java 标准库只支持 wav/mp3 等少数几种，amr 基本无解</li><li>市面上各类音频编解码的鼻祖级工具就是 <strong>ffmpeg</strong>，它几乎支持所有主流音频/视频格式的转码</li><li>调用 ffmpeg 也简单，本质就是一行命令：<code>ffmpeg -i 输入.amr 输出.mp3</code></li></ul><p>所以设计思路是：<strong>Java 不做编解码，只做封装</strong>。把&quot;读取输入源 -&gt; 落成本地临时文件 -&gt; 拼 ffmpeg 命令 -&gt; 执行 -&gt; 输出文件&quot;这一套流程封装成链式的 <code>AudioWrapper</code>，让调用方几行代码搞定转码。</p><h3 id="环境安装注意事项" tabindex="-1"><a class="header-anchor" href="#环境安装注意事项" aria-hidden="true">#</a> 环境安装注意事项</h3><p>因为底层是靠命令行调用 <code>ffmpeg</code>，所以<strong>本机（或服务所在机器）必须安装 ffmpeg，并且 ffmpeg 可执行文件要能在 PATH 中找到</strong>。</p><p>安装方式（任选其一）：</p><ul><li>官网下载对应平台的安装包，配置好环境变量</li><li>linux 静态编译包，解压即用：</li></ul><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token shebang important">#!/bin/bash</span>
<span class="token comment">## download ffmpeg cmd</span>
<span class="token function">wget</span> https://johnvansickle.com/ffmpeg/releases/ffmpeg-release-64bit-static.tar.xz

<span class="token comment">## exact package</span>
xz <span class="token parameter variable">-d</span> ffmpeg-release-64bit-static.tar.xz
<span class="token function">tar</span> <span class="token parameter variable">-xvf</span> ffmpeg-release-64bit-static.tar
<span class="token function">mv</span> ffmpeg-release-64bit-static ffmpeg
<span class="token builtin class-name">cd</span> ffmpeg
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>装完之后先手动验证一下：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>ffmpeg <span class="token parameter variable">-version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>能正常输出版本信息，说明环境 OK。<strong>强烈建议在写代码之前，先手动执行一次转码命令验证环境</strong>，比如准备一个 <code>test.amr</code> 文件：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>ffmpeg <span class="token parameter variable">-i</span> test.amr test.mp3
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>如果播放器能正常播放 <code>test.mp3</code>，后面用插件就不太可能有问题；反过来，如果环境没装好，插件执行命令时只会默默失败，排查起来反而多绕一圈。</p><blockquote><p><strong>注意</strong>：不要直接拿微信聊天记录里的语音文件来测试，微信对语音做过特殊处理，不是标准的 amr 文件，可能导致转码异常或时长不对。手头没有测试文件的话，项目测试目录里有一个标准的 <code>test.amr</code>。</p></blockquote><h2 id="ii-依赖引入" tabindex="-1"><a class="header-anchor" href="#ii-依赖引入" aria-hidden="true">#</a> II. 依赖引入</h2><p>项目已发布到 maven 中央仓库，直接依赖即可，请注意使用最新版本：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token comment">&lt;!-- https://mvnrepository.com/artifact/com.github.liuyueyi.media/audio-plugin --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>dependency</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>com.github.liuyueyi.media<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>audio-plugin<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>version</span><span class="token punctuation">&gt;</span></span>3.1.0<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>version</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>dependency</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>gradle 用户：</p><div class="language-groovy line-numbers-mode" data-ext="groovy"><pre class="language-groovy"><code><span class="token comment">// https://mvnrepository.com/artifact/com.github.liuyueyi.media/audio-plugin</span>
implementation <span class="token string">&#39;com.github.liuyueyi.media:audio-plugin:3.1.0&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>如果使用的是旧版本坐标 <code>com.github.hui.media:audio-plugin</code>（如 1.0），则需要额外添加作者的 maven 仓库源：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>repositories</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>repository</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>id</span><span class="token punctuation">&gt;</span></span>yihui-maven-repo<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>id</span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>url</span><span class="token punctuation">&gt;</span></span>https://raw.githubusercontent.com/liuyueyi/maven-repository/master/repository<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>url</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>repository</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>repositories</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></blockquote><h2 id="iii-使用姿势" tabindex="-1"><a class="header-anchor" href="#iii-使用姿势" aria-hidden="true">#</a> III. 使用姿势</h2><h3 id="_3-1-最简单的示例" tabindex="-1"><a class="header-anchor" href="#_3-1-最简单的示例" aria-hidden="true">#</a> 3.1 最简单的示例</h3><p>先看一个可运行的完整 case，对应测试类 <code>AudioWrapperTest</code>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">AudioWrapperTest</span> <span class="token punctuation">{</span>

    <span class="token annotation punctuation">@Test</span>
    <span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testAudioParse</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span> arys <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">String</span><span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">{</span><span class="token string">&quot;test.amr&quot;</span><span class="token punctuation">,</span>
                <span class="token string">&quot;http://s11.mogucdn.com/mlcdn/c45406/170713_3g25ec8fak8jch5349jd2dcafh61c.amr&quot;</span><span class="token punctuation">}</span><span class="token punctuation">;</span>

        <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token class-name">String</span> src <span class="token operator">:</span> arys<span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token class-name">String</span> output <span class="token operator">=</span> <span class="token class-name">AudioWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span>src<span class="token punctuation">)</span>
                    <span class="token punctuation">.</span><span class="token function">setInputType</span><span class="token punctuation">(</span><span class="token string">&quot;amr&quot;</span><span class="token punctuation">)</span>
                    <span class="token punctuation">.</span><span class="token function">setOutputType</span><span class="token punctuation">(</span><span class="token string">&quot;mp3&quot;</span><span class="token punctuation">)</span>
                    <span class="token punctuation">.</span><span class="token function">asFile</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span>output<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>上面这个循环分别测试了两种输入源：一个是从 classpath 加载的相对路径文件 <code>test.amr</code>，一个是网络音频 url。执行后输出（以 mac 为例）：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>/Users/yihui/<span class="token punctuation">..</span>./target/test-classes/test_out.mp3
/tmp/quickmedia/20261112/170713_3g25ec8fak8jch5349jd2dcafh61c_out.mp3
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>注意返回值 <code>output</code> 是<strong>转码后输出文件的绝对路径</strong>，文件名规则是 <code>原文件名_out.输出格式</code>。</p><p>可以看到使用姿势非常简洁，三段式：</p><ul><li><code>AudioWrapper.of(...)</code> 指定输入源，返回一个 <code>Builder</code> 对象</li><li><code>setInputType</code> / <code>setOutputType</code> 等链式调用配置参数</li><li><code>asFile()</code> / <code>asStream()</code> 表示执行转码并按指定方式输出</li></ul><h3 id="_3-2-三种输入源" tabindex="-1"><a class="header-anchor" href="#_3-2-三种输入源" aria-hidden="true">#</a> 3.2 三种输入源</h3><p><code>AudioWrapper</code> 提供了三个 <code>of</code> 方法，对应三种输入源：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">Builder</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">&gt;</span></span> <span class="token function">of</span><span class="token punctuation">(</span><span class="token class-name">String</span> str<span class="token punctuation">)</span><span class="token punctuation">;</span>           <span class="token comment">// 路径或 url 字符串</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">Builder</span><span class="token generics"><span class="token punctuation">&lt;</span>URI<span class="token punctuation">&gt;</span></span> <span class="token function">of</span><span class="token punctuation">(</span><span class="token class-name">URI</span> uri<span class="token punctuation">)</span><span class="token punctuation">;</span>                 <span class="token comment">// 网络资源</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">Builder</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">InputStream</span><span class="token punctuation">&gt;</span></span> <span class="token function">of</span><span class="token punctuation">(</span><span class="token class-name">InputStream</span> inputStream<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 输入流</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>其中 String 类型最常用，内部会按下面三种情况区分处理：</p><table><thead><tr><th style="text-align:center;">输入形式</th><th style="text-align:center;">处理方式</th><th style="text-align:center;">临时文件位置</th></tr></thead><tbody><tr><td style="text-align:center;"><code>http</code> 开头的 url</td><td style="text-align:center;">先下载到临时目录</td><td style="text-align:center;">临时目录，如 <code>/tmp/quickmedia/20261112/</code></td></tr><tr><td style="text-align:center;">绝对路径（如 <code>/a/b/test.amr</code>）</td><td style="text-align:center;">直接使用</td><td style="text-align:center;">原文件所在目录</td></tr><tr><td style="text-align:center;">相对路径（如 <code>test.amr</code>）</td><td style="text-align:center;">从 classpath 中解析</td><td style="text-align:center;">解析后的实际目录</td></tr><tr><td style="text-align:center;"><code>~/</code> 开头</td><td style="text-align:center;">展开用户目录后按绝对路径处理</td><td style="text-align:center;">原文件所在目录</td></tr></tbody></table><p>临时目录的默认规则（见 <code>FileWriteUtil</code>）：</p><ul><li>linux/mac：<code>/tmp/quickmedia/</code>，windows：<code>C://tmp/quickmedia/</code></li><li>目录后面会拼接当天日期（如 <code>20261112</code>），按天归档</li><li>可以通过系统属性 <code>quick.media.tmp.path</code> 自定义，比如启动参数 <code>-Dquick.media.tmp.path=/data/tmp</code></li></ul><h3 id="_3-3-输出方式-asfile-与-asstream" tabindex="-1"><a class="header-anchor" href="#_3-3-输出方式-asfile-与-asstream" aria-hidden="true">#</a> 3.3 输出方式：asFile 与 asStream</h3><p><code>asFile()</code> 返回输出文件的绝对路径，转码失败时返回 <code>null</code>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">String</span> output <span class="token operator">=</span> <span class="token class-name">AudioWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token string">&quot;test.amr&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">setInputType</span><span class="token punctuation">(</span><span class="token string">&quot;amr&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">setOutputType</span><span class="token punctuation">(</span><span class="token string">&quot;mp3&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">asFile</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果不想落成磁盘上的目标文件再读，而是希望直接拿到流（比如 web 场景转完直接写回响应），用 <code>asStream()</code>，它内部就是先 <code>asFile()</code> 再读输出文件：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">InputStream</span> stream <span class="token operator">=</span> <span class="token class-name">AudioWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token string">&quot;test.amr&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">setInputType</span><span class="token punctuation">(</span><span class="token string">&quot;amr&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">setOutputType</span><span class="token punctuation">(</span><span class="token string">&quot;mp3&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">asStream</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-4-输入流方式的注意事项" tabindex="-1"><a class="header-anchor" href="#_3-4-输入流方式的注意事项" aria-hidden="true">#</a> 3.4 输入流方式的注意事项</h3><p><code>InputStream</code> 方式比较特殊，因为流本身没有文件名，<strong>必须通过 <code>setInputType</code> 指定源音频格式</strong>，插件会用 <code>时间戳_随机数.格式</code> 在临时目录生成临时源文件，否则临时文件没有后缀，ffmpeg 可能无法识别格式：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">try</span> <span class="token punctuation">(</span><span class="token class-name">InputStream</span> in <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">FileInputStream</span><span class="token punctuation">(</span><span class="token string">&quot;/a/b/xxx.amr&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">String</span> output <span class="token operator">=</span> <span class="token class-name">AudioWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span>in<span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">setInputType</span><span class="token punctuation">(</span><span class="token string">&quot;amr&quot;</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">setOutputType</span><span class="token punctuation">(</span><span class="token string">&quot;mp3&quot;</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">asFile</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>对应的，路径/url 方式下后缀是从文件名里解析的，<code>setInputType</code> 可以省略；但保险起见，官方测试用例里两种场景都显式设置了 <code>setInputType</code>，建议保持一致。</p><h2 id="iv-参数说明" tabindex="-1"><a class="header-anchor" href="#iv-参数说明" aria-hidden="true">#</a> IV. 参数说明</h2><p><code>AudioWrapper.Builder</code> 上可用的配置方法如下：</p><table><thead><tr><th style="text-align:center;">方法</th><th style="text-align:center;">说明</th><th style="text-align:center;">是否必须</th></tr></thead><tbody><tr><td style="text-align:center;"><code>of(...)</code></td><td style="text-align:center;">指定输入源，支持 String/URI/InputStream</td><td style="text-align:center;">必须</td></tr><tr><td style="text-align:center;"><code>setInputType(String)</code></td><td style="text-align:center;">源音频格式（后缀名，如 <code>amr</code>）；InputStream 输入源必须设置</td><td style="text-align:center;">视输入源而定</td></tr><tr><td style="text-align:center;"><code>setOutputType(String)</code></td><td style="text-align:center;">输出音频格式（后缀名，如 <code>mp3</code>）</td><td style="text-align:center;">必须，缺失时直接抛异常</td></tr><tr><td style="text-align:center;"><code>addOption(String, Object)</code></td><td style="text-align:center;">追加 ffmpeg 命令行参数，如 <code>addOption(&quot;ar&quot;, 44100)</code></td><td style="text-align:center;">可选</td></tr><tr><td style="text-align:center;"><code>asFile()</code></td><td style="text-align:center;">执行转码，返回输出文件绝对路径，失败返回 null</td><td style="text-align:center;">二选一</td></tr><tr><td style="text-align:center;"><code>asStream()</code></td><td style="text-align:center;">执行转码，返回输出文件的输入流</td><td style="text-align:center;">二选一</td></tr></tbody></table><p>插件内部还会默认追加三个兜底参数（在 <code>Builder</code> 的构造器里，不想要可以 <code>addOption</code> 覆盖）：</p><table><thead><tr><th style="text-align:center;">默认参数</th><th style="text-align:center;">作用</th></tr></thead><tbody><tr><td style="text-align:center;"><code>-y</code></td><td style="text-align:center;">覆盖写，输出文件已存在时直接覆盖；不加这个，ffmpeg 在遇到同名文件时会交互式等待输入 y/n，代码里进程会一直卡住</td></tr><tr><td style="text-align:center;"><code>write_xing 0</code></td><td style="text-align:center;">解决 mac/ios 播放器显示音频时长不对的问题</td></tr><tr><td style="text-align:center;"><code>loglevel quiet</code></td><td style="text-align:center;">不输出 ffmpeg 日志，避免输出流无人消费的问题</td></tr></tbody></table><p>最终拼装出来的命令形如：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>ffmpeg <span class="token parameter variable">-i</span> /tmp/quickmedia/20261112/xxx.amr <span class="token parameter variable">-y</span> <span class="token parameter variable">-write_xing</span> <span class="token number">0</span> <span class="token parameter variable">-loglevel</span> quiet /tmp/quickmedia/20261112/xxx_out.mp3
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>命令的执行由 <code>ProcessUtil</code> 完成，它做了几件细节工作：用独立线程消费命令行的输出流和异常流（防止缓冲区写满导致进程阻塞）、设置 2 秒的超时时间避免死等。</p><h2 id="v-常见坑" tabindex="-1"><a class="header-anchor" href="#v-常见坑" aria-hidden="true">#</a> V. 常见坑</h2><p>最后汇总一下实际使用中踩过的坑：</p><h3 id="_1-环境未安装-ffmpeg" tabindex="-1"><a class="header-anchor" href="#_1-环境未安装-ffmpeg" aria-hidden="true">#</a> 1. 环境未安装 ffmpeg</h3><p>所有转码都依赖本机的 <code>ffmpeg</code> 命令，没装环境的话，执行时会在日志里输出 <code>operate audio error! cmd: ...</code>，<code>asFile</code> 返回 <code>null</code>。部署到新机器上，先跑 <code>ffmpeg -version</code> 再上线。</p><h3 id="_2-mac-ios-下音频时长显示不对" tabindex="-1"><a class="header-anchor" href="#_2-mac-ios-下音频时长显示不对" aria-hidden="true">#</a> 2. mac/ios 下音频时长显示不对</h3><p>amr 转 mp3 后，在某些播放器（尤其 mac 和 iphone）上显示的时长比实际小，但播放本身没问题。原因和 mp3 头部的时长信息有关，解决方式就是插件默认加的 <code>write_xing 0</code> 参数；如果手动覆盖默认参数时把它弄丢了，这个坑就会重新出现。</p><h3 id="_3-大文件转码超时" tabindex="-1"><a class="header-anchor" href="#_3-大文件转码超时" aria-hidden="true">#</a> 3. 大文件转码超时</h3><p><code>ProcessUtil</code> 对命令执行设置了 2 秒超时，超过 2 秒会抛 <code>TimeoutException</code>，<code>asFile</code> 会捕获并返回 <code>null</code>。对大文件或者高负载机器需要注意这一点；并且超时后插件并不会主动终止 ffmpeg 进程，如果遇到这种场景，建议基于源码自行调整超时或干脆直接封装 <code>Runtime.exec</code> 自己控制。</p><h3 id="_4-并发场景下-rt-线性增加" tabindex="-1"><a class="header-anchor" href="#_4-并发场景下-rt-线性增加" aria-hidden="true">#</a> 4. 并发场景下 RT 线性增加</h3><p>早期版本没有处理命令行的输出流、异常流，也不输出日志，导致并发一高，rt 就线性上涨——根本原因是 ffmpeg 的输出/异常信息没人消费，缓存它们的空间有限，把进程卡住了。当前版本的处理方式有两条：独立线程消费输出流/异常流，以及默认 <code>loglevel quiet</code> 不产生日志。如果你 <code>addOption</code> 时把日志重新打开，在并发场景要留意这个坑。</p><h3 id="_5-微信语音不是标准的-amr" tabindex="-1"><a class="header-anchor" href="#_5-微信语音不是标准的-amr" aria-hidden="true">#</a> 5. 微信语音不是标准的 amr</h3><p>直接拿微信里导出的语音文件测试，可能转码报错或时长不对，这不是插件的锅。测试请用标准 amr 文件。</p><h3 id="_6-临时文件与输出文件" tabindex="-1"><a class="header-anchor" href="#_6-临时文件与输出文件" aria-hidden="true">#</a> 6. 临时文件与输出文件</h3><ul><li>输出文件名固定为 <code>原文件名_out.输出格式</code>，输出目录与临时源文件同目录，多次转码同名文件时靠默认 <code>-y</code> 覆盖</li><li>网络资源/输入流的临时文件都在 <code>/tmp/quickmedia/yyyyMMdd/</code>（win 为 <code>C://tmp/quickmedia/yyyyMMdd/</code>），按天归档，不会自动清理，需要业务方自己定期清理磁盘，或者用 <code>quick.media.tmp.path</code> 把目录指到有清理机制的地方</li><li>windows 下临时路径里是 <code>C://tmp/...</code> 这种写法，注意不要和防火墙/权限策略冲突</li></ul><h2 id="vi-小结" tabindex="-1"><a class="header-anchor" href="#vi-小结" aria-hidden="true">#</a> VI. 小结</h2><p>本篇介绍了 audio-plugin 的核心能力：基于 ffmpeg 的音频转码。整体使用非常简单：<code>of()</code> 定输入源，<code>setInputType</code>/<code>setOutputType</code> 定格式，<code>asFile()</code>/<code>asStream()</code> 定输出方式，剩下的下载临时文件、拼命令、执行、输出文件名管理都由插件兜底。</p>`,71),m=n("strong",null,"项目地址：",-1),k={href:"https://github.com/liuyueyi/quick-media",target:"_blank",rel:"noopener noreferrer"},g=n("p",null,[n("strong",null,"延伸阅读：")],-1),v={href:"https://my.oschina.net/u/566591/blog/1359432",target:"_blank",rel:"noopener noreferrer"};function h(b,f){const s=l("ExternalLinkIcon");return p(),c("div",null,[u,o(" more "),r,n("p",null,[m,a(),n("a",k,[a("https://github.com/liuyueyi/quick-media"),e(s)])]),g,n("ul",null,[n("li",null,[n("a",v,[a("spring-boot & ffmpeg 搭建一个音频转码服务"),e(s)])])])])}const x=t(d,[["render",h],["__file","01.基于FFMPEG实现音频转码.html.vue"]]);export{x as default};
